python3 -c "
html = '''<!DOCTYPE html>
<html>
<head>
<meta charset=\"UTF-8\">
<meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">
<title>Super Mario</title>
<style>
*{margin:0;padding:0;box-sizing:border-box}
body{background:#000;display:flex;justify-content:center;align-items:center;height:100vh;overflow:hidden;flex-direction:column}
canvas{border:2px solid #333;image-rendering:pixelated}
#info{color:#888;font-family:monospace;margin-top:10px;font-size:14px}
</style>
</head>
<body>
<canvas id=\"game\"></canvas>
<div id=\"info\">← → 移动 | 空格/↑ 跳跃 | R 重开</div>
<script>
const canvas=document.getElementById('game');
const ctx=canvas.getContext('2d');
const W=800,H=480;
canvas.width=W;canvas.height=H;

// ============ CONSTANTS ============
const TILE=32;
const GRAVITY=0.55;
const FRICTION=0.82;
const MAX_SPEED=4.5;
const JUMP=-10;

// ============ LEVEL 1-1 ============
const level=[
  '................................................................................',
  '................................................................................',
  '................................................................................',
  '................................................................................',
  '................................................................................',
  '................................................................................',
  '................................................................................',
  '................................................................................',
  '................................................................................',
  '................................................................................',
  '................................................................................',
  '...........................................................................T....',
  '...........................................................................TTTTT.',
  '......................................................T.........................',
  '.....................TTT................................TTTT......................',
  '.................T...................................TTTTTTTT..................T.',
  '.......TTT.............................................TTTT................TTTTT.',
  '................................................................................',
  '..............................................................T.........TTTT......',
  '..P.......?..............?..........?.......T..........TTTTTTTTTTTTTTTTTTTT.....',
  'TTTTTTTTTTTTTTTTTTTTTTTTTTTTTTTTTTTTTTTTTTTTTTTTTTTTTTTTTTTTTTTTTTTTTTTTTTTTTTTT',
].map(r=>r.split(''));

const COLORS={G:'#8B4513','?':'#FFD700',T:'#00AA00',P:'#FF0000'};

// ============ GAME STATE ============
let game={};
function resetGame(){
  game={
    cam:{x:0,y:0},
    player:{x:64,y:320,w:24,h:32,vx:0,vy:0,onGround:false,jumping:false,alive:true,facing:1,frame:0,frameTimer:0},
    enemies:[],
    coins:0,
    gameOver:false,
    win:false,
    particles:[]
  };
  // Find player spawn
  for(let r=0;r<level.length;r++){
    for(let c=0;c<level[r].length;c++){
      if(level[r][c]=='P'){
        game.player.x=c*TILE+4;
        game.player.y=r*TILE-8;
        level[r][c]='.';
      }
      if(level[r][c]=='E'){
        game.enemies.push({x:c*TILE,y:r*TILE,w:28,h:28,vx:-1,alive:true,frame:0});
        level[r][c]='.';
      }
    }
  }
}
resetGame();

// ============ INPUT ============
const keys={};
document.addEventListener('keydown',e=>{
  keys[e.code]=true;
  if(e.code=='Space'||e.code=='ArrowUp')e.preventDefault();
  if(e.code=='KeyR')resetGame();
});
document.addEventListener('keyup',e=>keys[e.code]=false);

// ============ COLLISION ============
function tileAt(x,y){
  const c=Math.floor(x/TILE),r=Math.floor(y/TILE);
  if(r<0||r>=level.length||c<0||c>=level[0].length)return '#';
  return level[r][c];
}

function isSolid(t){return t=='T'||t=='G'||t=='?'||t=='B';}

function rectCollide(a,b){
  return a.x<b.x+b.w&&a.x+a.w>b.x&&a.y<b.y+b.h&&a.y+a.h>b.y;
}

// ============ UPDATE ============
function update(){
  const p=game.player;
  if(!p.alive||game.gameOver||game.win)return;

  // Input
  if(keys['ArrowLeft']){p.vx-=0.4;p.facing=-1;}
  if(keys['ArrowRight']){p.vx+=0.4;p.facing=1;}
  if((keys['Space']||keys['ArrowUp'])&&p.onGround&&!p.jumping){
    p.vy=JUMP;p.jumping=true;p.onGround=false;
  }
  if(!keys['Space']&&!keys['ArrowUp'])p.jumping=false;

  // Physics
  p.vx*=FRICTION;
  if(Math.abs(p.vx)>MAX_SPEED)p.vx=Math.sign(p.vx)*MAX_SPEED;
  if(Math.abs(p.vx)<0.1)p.vx=0;

  p.vy+=GRAVITY;
  if(p.vy>12)p.vy=12;

  // Horizontal collision
  p.x+=p.vx;
  if(p.vx>0){
    if(isSolid(tileAt(p.x+p.w,p.y))||isSolid(tileAt(p.x+p.w,p.y+p.h-4))){
      p.x=Math.floor((p.x+p.w)/TILE)*TILE-p.w;
      p.vx=0;
    }
  }else if(p.vx<0){
    if(isSolid(tileAt(p.x,p.y))||isSolid(tileAt(p.x,p.y+p.h-4))){
      p.x=Math.floor(p.x/TILE)*TILE+TILE;
      p.vx=0;
    }
  }

  // Vertical collision
  p.y+=p.vy;
  p.onGround=false;
  if(p.vy>0){
    if(isSolid(tileAt(p.x,p.y+p.h))||isSolid(tileAt(p.x+p.w,p.y+p.h))){
      p.y=Math.floor((p.y+p.h)/TILE)*TILE-p.h;
      p.vy=0;p.onGround=true;
    }
  }else if(p.vy<0){
    if(isSolid(tileAt(p.x,p.y))||isSolid(tileAt(p.x+p.w,p.y))){
      p.y=Math.floor(p.y/TILE)*TILE+TILE;
      p.vy=0;
      // Hit block from below
      const bx=Math.floor(p.x/TILE),by=Math.floor((p.y-1)/TILE);
      if(by>=0&&by<level.length&&bx>=0&&bx<level[0].length){
        if(level[by][bx]=='?'){
          level[by][bx]='B';
          game.coins++;
          // Coin particle
          for(let i=0;i<6;i++){
            game.particles.push({x:bx*TILE+TILE/2,y:by*TILE,vx:(Math.random()-0.5)*3,vy:-Math.random()*5-2,life:30,color:'#FFD700'});
          }
        }
      }
    }
  }

  // Animation
  if(Math.abs(p.vx)>0.5&&p.onGround){
    p.frameTimer++;
    if(p.frameTimer>6){p.frame=(p.frame+1)%3;p.frameTimer=0;}
  }else if(p.onGround){p.frame=0;p.frameTimer=0;}

  // Fall death
  if(p.y>H+100){p.alive=false;game.gameOver=true;}

  // Camera
  game.cam.x=p.x-W/3;
  game.cam.x=Math.max(0,Math.min(game.cam.x,level[0].length*TILE-W));
  game.cam.y=0;

  // Enemies
  for(const e of game.enemies){
    if(!e.alive){e.vy=(e.vy||0)+0.5;e.y+=e.vy;e.x+=e.vx||0;continue;}
    e.x+=e.vx;
    // Wall collision
    if(isSolid(tileAt(e.x+e.w,e.y+4))||isSolid(tileAt(e.x+e.w,e.y+e.h-4))){e.vx=-e.vx;e.x+=e.vx*2;}
    if(isSolid(tileAt(e.x,e.y+4))||isSolid(tileAt(e.x,e.y+e.h-4))){e.vx=-e.vx;e.x+=e.vx*2;}
    // Floor
    if(!isSolid(tileAt(e.x+4,e.y+e.h))&&!isSolid(tileAt(e.x+e.w-4,e.y+e.h))){e.vx=-e.vx;}
    // Player collision
    if(rectCollide(p,e)){
      if(p.vy>0&&p.y+p.h-e.y<16){
        e.alive=false;e.vy=-5;
        p.vy=-8;game.coins+=5;
        for(let i=0;i<10;i++){
          game.particles.push({x:e.x+e.w/2,y:e.y+e.h/2,vx:(Math.random()-0.5)*5,vy:(Math.random()-0.5)*5-2,life:20,color:'#8B4513'});
        }
      }else{
        p.alive=false;game.gameOver=true;
      }
    }
    e.frame=(e.frame+1)%4;
  }

  // Particles
  game.particles=game.particles.filter(pt=>{
    pt.x+=pt.vx;pt.y+=pt.vy;pt.vy+=0.1;pt.life--;
    return pt.life>0;
  });
}

// ============ DRAW ============
function draw(){
  ctx.fillStyle='#5C94FC';
  ctx.fillRect(0,0,W,H);

  ctx.save();
  ctx.translate(-game.cam.x,-game.cam.y);

  const startCol=Math.max(0,Math.floor(game.cam.x/TILE)-1);
  const endCol=Math.min(level[0].length,Math.ceil((game.cam.x+W)/TILE)+1);

  // Draw tiles
  for(let r=0;r<level.length;r++){
    for(let c=startCol;c<endCol;c++){
      const t=level[r][c];
      const x=c*TILE,y=r*TILE;
      if(t=='T'){
        ctx.fillStyle='#8B4513';
        ctx.fillRect(x,y,TILE,TILE);
        ctx.strokeStyle='#6B3410';
        ctx.lineWidth=1;
        ctx.strokeRect(x,y,TILE,TILE);
        // Brick pattern
        ctx.fillStyle='#A0522D';
        ctx.fillRect(x+2,y+2,12,12);
        ctx.fillRect(x+18,y+2,12,12);
        ctx.fillRect(x+10,y+18,12,12);
      }else if(t=='G'){
        ctx.fillStyle='#FFD700';
        ctx.fillRect(x,y,TILE,TILE);
        ctx.strokeStyle='#DAA520';
        ctx.lineWidth=1;
        ctx.strokeRect(x,y,TILE,TILE);
        ctx.fillStyle='#FFF8DC';
        ctx.fillRect(x+4,y+4,8,8);
      }else if(t=='?'){
        ctx.fillStyle='#FFD700';
        ctx.fillRect(x,y,TILE,TILE);
        ctx.strokeStyle='#B8860B';
        ctx.lineWidth=2;
        ctx.strokeRect(x,y,TILE,TILE);
        ctx.fillStyle='#FFF';
        ctx.font='24px monospace';
        ctx.textAlign='center';
        ctx.fillText('?',x+TILE/2,y+TILE-6);
      }else if(t=='B'){
        ctx.fillStyle='#B8860B';
        ctx.fillRect(x,y,TILE,TILE);
        ctx.strokeStyle='#8B6914';
        ctx.lineWidth=1;
        ctx.strokeRect(x,y,TILE,TILE);
      }
    }
  }

  // Draw enemies
  for(const e of game.enemies){
    const ex=e.x-game.cam.x,ey=e.y-game.cam.y;
    if(ex<-50||ex>W+50)continue;
    ctx.fillStyle=e.alive?'#8B0000':'#666';
    ctx.fillRect(ex,ey,e.w,e.h);
    if(e.alive){
      // Eyes
      ctx.fillStyle='#FFF';
      ctx.fillRect(ex+6,ey+6,6,6);
      ctx.fillRect(ex+16,ey+6,6,6);
      ctx.fillStyle='#000';
      ctx.fillRect(ex+8+(e.vx<0?0:2),ey+8,3,3);
      ctx.fillRect(ex+18+(e.vx<0?0:2),ey+8,3,3);
      // Feet
      ctx.fillStyle='#A52A2A';
      const foff=Math.sin(Date.now()/100)*3;
      ctx.fillRect(ex+4,ey+e.h-8+foff,8,8);
      ctx.fillRect(ex+16,ey+e.h-8-foff,8,8);
    }
  }

  // Draw player
  const px=p.x-game.cam.x,py=p.y-game.cam.y;
  if(p.alive){
    // Body
    ctx.fillStyle='#FF0000';
    ctx.fillRect(px+2,py+4,20,16);
    // Head
    ctx.fillStyle='#FFB6C1';
    ctx.fillRect(px+4,py,16,12);
    // Hat
    ctx.fillStyle='#FF0000';
    ctx.fillRect(px+2,py-2,22,6);
    // Eyes
    ctx.fillStyle='#000';
    const eyeOff=game.player.facing>0?0:2;
    ctx.fillRect(px+8+eyeOff,py+3,3,3);
    ctx.fillRect(px+14+eyeOff,py+3,3,3);
    // Legs
    ctx.fillStyle='#0000FF';
    if(p.onGround&&Math.abs(p.vx)>0.5){
      const loff=Math.sin(Date.now()/80)*4;
      ctx.fillRect(px+4,py+20,8,12);
      ctx.fillRect(px+14,py+20,8,12-loff);
    }else if(!p.onGround){
      ctx.fillRect(px+4,py+20,6,12);
      ctx.fillRect(px+16,py+20,6,8);
    }else{
      ctx.fillRect(px+4,py+20,7,12);
      ctx.fillRect(px+15,py+20,7,12);
    }
    // Mustache
    ctx.fillStyle='#8B4513';
    ctx.fillRect(px+6,py+8,14,3);
  }else{
    // Dead
    ctx.fillStyle='#FF0000';
    ctx.fillRect(px,py,24,16);
    ctx.fillStyle='#FFF';
    ctx.font='12px monospace';
    ctx.fillText('X',px+8,py+12);
  }

  ctx.restore();

  // HUD
  ctx.fillStyle='#FFF';
  ctx.font='bold 18px monospace';
  ctx.fillText('COINS: '+game.coins,20,30);
  ctx.fillText('MARIO',W/2-40,30);

  if(game.gameOver){
    ctx.fillStyle='rgba(0,0,0,0.7)';
    ctx.fillRect(0,0,W,H);
    ctx.fillStyle='#FF0000';
    ctx.font='bold 48px monospace';
    ctx.textAlign='center';
    ctx.fillText('GAME OVER',W/2,H/2-20);
    ctx.fillStyle='#FFF';
    ctx.font='18px monospace';
    ctx.fillText('Press R to restart',W/2,H/2+30);
  }

  if(game.win){
    ctx.fillStyle='rgba(0,0,0,0.5)';
    ctx.fillRect(0,0,W,H);
    ctx.fillStyle='#FFD700';
    ctx.font='bold 48px monospace';
    ctx.textAlign='center';
    ctx.fillText('YOU WIN!',W/2,H/2-20);
    ctx.fillStyle='#FFF';
    ctx.font='18px monospace';
    ctx.fillText('Coins: '+game.coins,W/2,H/2+30);
  }

  // Particles
  for(const pt of game.particles){
    ctx.fillStyle=pt.color;
    const px2=pt.x-game.cam.x,py2=pt.y-game.cam.y;
    ctx.fillRect(px2,py2,4,4);
  }
}

// ============ GAME LOOP ============
function gameLoop(){
  update();
  draw();
  requestAnimationFrame(gameLoop);
}
gameLoop();
</script>
</body>
</html>'''

with open('/root/.nanobot/workspace/mario_game/build/web/game.html','w') as f:
    f.write(html)
print('Written OK, size:',len(html))
"
